veloI18n.lang = (() => { try { const l = (globalThis.chrome || globalThis.browser).i18n.getUILanguage().toLowerCase();
  if (l.startsWith("pt")) return "pt-BR"; if (l.startsWith("zh")) return "zh-CN"; const b = l.split("-")[0];
  return veloI18n.STRINGS[b] ? b : "en"; } catch { return "en"; } })();
veloI18n.load(veloI18n.STRINGS[veloI18n.lang] || {});
